// src/pages/KidsClothing.js
import React, { useState } from 'react';
import { useCart } from '../component/GioHang/CartContext';
import './MensClothing.css'; // dùng chung CSS cho đẹp

const KidClothing = () => {
    const { addToCart } = useCart();
    const [filterPrice, setFilterPrice] = useState('');

    const products = [
        {
            id: 1,
            name: "Áo thun bé trai",
            description: "Chất liệu cotton êm ái, thiết kế năng động.",
            image: "/assets/kid-shirt.jpg",
            price: 180000
        },
        {
            id: 2,
            name: "Đầm công chúa bé gái",
            description: "Phong cách dễ thương, phù hợp tiệc sinh nhật.",
            image: "/assets/kid-dress.jpg",
            price: 270000
        },
        {
            id: 3,
            name: "Bộ đồ chơi năng động",
            description: "Set đồ thoải mái cho bé chạy nhảy cả ngày.",
            image: "/assets/kid-outfit.jpg",
            price: 230000
        }
    ];

    const filteredProducts = products.filter(item => {
        if (filterPrice === '') return true;
        if (filterPrice === 'lt200') return item.price < 200000;
        if (filterPrice === '200to250') return item.price >= 200000 && item.price <= 250000;
        if (filterPrice === 'gt250') return item.price > 250000;
        return true;
    });

    return (
        <div className="container mt-5 mb-5">
            <h2 className="text-center fw-bold text-uppercase mb-4">Thời trang trẻ em</h2>
            <div className="row">
                {/* Bộ lọc bên trái */}
                <div className="col-md-3 mb-4">
                    <div className="card p-3 shadow-sm filter-box">
                        <h5 className="mb-3 text-success">Bộ lọc</h5>
                        <div className="mb-3">
                            <label className="form-label">Giá tiền:</label>
                            <select
                                className="form-select"
                                value={filterPrice}
                                onChange={(e) => setFilterPrice(e.target.value)}
                            >
                                <option value="">Tất cả</option>
                                <option value="lt200">Dưới 200.000₫</option>
                                <option value="200to250">Từ 200.000₫ - 250.000₫</option>
                                <option value="gt250">Trên 250.000₫</option>
                            </select>
                        </div>
                    </div>
                </div>

                {/* Danh sách sản phẩm bên phải */}
                <div className="col-md-9">
                    <div className="row">
                        {filteredProducts.map((item) => (
                            <div className="col-md-4 mb-4" key={item.id}>
                                <div className="card h-100 shadow-sm rounded-lg overflow-hidden product-card">
                                    <img
                                        src={item.image}
                                        className="card-img-top"
                                        alt={item.name}
                                        style={{ height: "300px", objectFit: "cover" }}
                                    />
                                    <div className="card-body text-center">
                                        <h5 className="card-title">{item.name}</h5>
                                        <p className="card-text">{item.description}</p>
                                        <p className="fw-bold text-primary">
                                            {item.price.toLocaleString()}₫
                                        </p>
                                        <button
                                            className="btn btn-outline-success rounded-pill w-75"
                                            onClick={() => addToCart(item)}
                                        >
                                            Thêm vào giỏ hàng
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="text-center text-muted">Không có sản phẩm phù hợp.</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default KidClothing;
